for t in range(int(input())):
	n = int(input())
	arr = list(map(int, input().split()))
	arr.sort()
	if n == 1:
		print(1)
	else:
		c = 0
		ans = 0
		ch = 1
		for i in range(n):
			if arr[i] <= 2 ** ch - 1:
				c += 1
			else:
				ans += c * (c - 1) // 2
				c = 1
				ch += 1
		if c > 1:
			ans += c * (c - 1) // 2
		print(ans)
